const request = $input.first().json;

/**
 * HTML forms submitted through the Webhook normally appear
 * inside request.body.
 *
 * The fallback also makes manual tests easier.
 */
const body =
  request.body &&
  typeof request.body === 'object'
    ? request.body
    : request;

function cleanSingleLine(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function cleanMultiline(value) {
  return String(value ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

const token = cleanSingleLine(body.token);

const reviewerName = cleanSingleLine(
  body.reviewer_name
);

const reviewerEmail = cleanSingleLine(
  body.reviewer_email
).toLowerCase();

const decision = cleanSingleLine(
  body.decision
);

const feedback = cleanMultiline(
  body.feedback
);

const errors = [];

if (!/^[a-f0-9]{64}$/i.test(token)) {
  errors.push(
    'The campaign review token is missing or invalid.'
  );
}

if (
  reviewerName.length < 2 ||
  reviewerName.length > 150
) {
  errors.push(
    'Reviewer name must contain 2 to 150 characters.'
  );
}

const emailPattern =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailPattern.test(reviewerEmail)) {
  errors.push(
    'Enter a valid reviewer email address.'
  );
}

const allowedDecisions = [
  'approved',
  'revision_requested',
  'rejected',
];

if (!allowedDecisions.includes(decision)) {
  errors.push(
    'Select Approve, Request Revision, or Reject.'
  );
}

if (feedback.length > 5000) {
  errors.push(
    'Feedback cannot exceed 5,000 characters.'
  );
}

/**
 * A revision request must explain what needs changing.
 */
if (
  decision === 'revision_requested' &&
  feedback.length < 5
) {
  errors.push(
    'Add clear revision instructions before requesting a new version.'
  );
}

/**
 * Rejections should also include a reason.
 */
if (
  decision === 'rejected' &&
  feedback.length < 5
) {
  errors.push(
    'Add a brief reason for rejecting the campaign.'
  );
}

const validationOk = errors.length === 0;

const errorHtml = `
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8">

    <meta
      name="viewport"
      content="width=device-width, initial-scale=1.0"
    >

    <title>Invalid Campaign Decision</title>

    <style>
      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        padding: 30px 16px;
        background: #f4f5f7;
        color: #202124;
        font-family: Arial, sans-serif;
        line-height: 1.6;
      }

      .card {
        max-width: 680px;
        margin: 60px auto;
        padding: 32px;
        background: white;
        border: 1px solid #dadce0;
        border-radius: 14px;
        box-shadow:
          0 6px 24px rgba(0, 0, 0, 0.08);
      }

      h1 {
        margin-top: 0;
      }

      li {
        margin-bottom: 8px;
      }

      button {
        padding: 12px 18px;
        border: 0;
        border-radius: 8px;
        background: #202124;
        color: white;
        cursor: pointer;
        font: inherit;
        font-weight: 700;
      }
    </style>
  </head>

  <body>
    <main class="card">
      <h1>We could not submit your decision</h1>

      <p>Please correct the following:</p>

      <ul>
        ${errors
          .map(
            (error) =>
              `<li>${escapeHtml(error)}</li>`
          )
          .join('')}
      </ul>

      <button onclick="history.back()">
        Return to the review
      </button>
    </main>
  </body>
</html>
`;

return [
  {
    json: {
      validation_ok: validationOk,
      validation_errors: errors,

      token,
      reviewer_name: reviewerName,
      reviewer_email: reviewerEmail,
      decision,
      feedback,

      db_payload: {
        token,
        reviewer_name: reviewerName,
        reviewer_email: reviewerEmail,
        decision,
        feedback,
      },

      html: errorHtml,
      status_code: validationOk ? 200 : 400,
    },
  },
];

const result = $input.first().json;

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

const statusCodes = {
  processed: 200,
  invalid_token: 404,
  already_decided: 409,
  expired: 410,
  conflict: 409,
};

let pageTitle =
  'Campaign decision unavailable';

let heading =
  'We could not process the decision';

let explanation =
  result.result_message;

let nextAction = '';

if (result.processed) {
  switch (result.decision) {
    case 'approved':
      pageTitle = 'Campaign Approved';
      heading = 'Campaign approved';
      explanation =
        'Your approval was saved successfully.';

      nextAction =
        'Production task creation has been added to the automation queue.';
      break;

    case 'revision_requested':
      pageTitle = 'Revision Requested';
      heading = 'Revision requested';
      explanation =
        'Your feedback and revision instructions were saved successfully.';

      nextAction =
        'A new AI campaign version has been added to the automation queue.';
      break;

    case 'rejected':
      pageTitle = 'Campaign Rejected';
      heading = 'Campaign rejected';
      explanation =
        'Your rejection and feedback were saved successfully.';

      nextAction =
        'No additional campaign work was queued.';
      break;
  }
}

const html = `
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8">

    <meta
      name="viewport"
      content="width=device-width, initial-scale=1.0"
    >

    <title>${escapeHtml(pageTitle)}</title>

    <style>
      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        padding: 30px 16px;
        background: #f4f5f7;
        color: #202124;
        font-family: Arial, sans-serif;
        line-height: 1.6;
      }

      .card {
        max-width: 720px;
        margin: 60px auto;
        padding: 34px;
        background: white;
        border: 1px solid #dadce0;
        border-radius: 14px;
        box-shadow:
          0 6px 24px rgba(0, 0, 0, 0.08);
      }

      h1 {
        margin-top: 0;
      }

      .reference {
        margin-top: 24px;
        padding: 16px;
        background: #f8f9fa;
        border: 1px solid #e3e5e8;
        border-radius: 8px;
      }

      .label {
        display: block;
        margin-bottom: 4px;
        color: #5f6368;
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.05em;
        text-transform: uppercase;
      }

      .success {
        display: inline-block;
        margin-bottom: 18px;
        padding: 6px 12px;
        background: #e6f4ea;
        border-radius: 999px;
        color: #137333;
        font-weight: 700;
      }

      .error {
        display: inline-block;
        margin-bottom: 18px;
        padding: 6px 12px;
        background: #fce8e6;
        border-radius: 999px;
        color: #c5221f;
        font-weight: 700;
      }
    </style>
  </head>

  <body>
    <main class="card">
      <span class="${
        result.processed
          ? 'success'
          : 'error'
      }">
        ${
          result.processed
            ? 'Decision saved'
            : 'Decision not saved'
        }
      </span>

      <h1>${escapeHtml(heading)}</h1>

      <p>${escapeHtml(explanation)}</p>

      ${
        nextAction
          ? `<p>${escapeHtml(nextAction)}</p>`
          : ''
      }

      ${
        result.campaign_code
          ? `
            <div class="reference">
              <span class="label">
                Campaign reference
              </span>

              ${escapeHtml(result.campaign_code)}
            </div>
          `
          : ''
      }

      <p>
        You may now close this page.
      </p>
    </main>
  </body>
</html>
`;

return [
  {
    json: {
      ...result,
      html,

      status_code:
        statusCodes[result.result_status] ??
        400,
    },
  },
];
